                    Strings.toString(block.chainid),
                    "&v=",
                    Strings.toHexString(uint160(_fundingVault), 20),
                    "&p="
                )
            );
    }

    function _beforeTokenTransfer(
        address from,
        address to,
        uint256 tokenId,
        uint256 batchSize
    ) internal virtual override {
